pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 public receivedCalls;

    function setUp() public {
        c = new C();
        receivedCalls = 0;
    }

    function testFuzz_property(uint256 amount, uint8 times) public {
        // Bound times to keep execution reasonable (1-20 calls)
        times = uint8(bound(uint256(times), 1, 20));
        // Bound amount to avoid overflow in total sent (max 1 ether per call to keep test practical)
        amount = bound(amount, 0, 1 ether);

        // Track how many receive calls we actually make
        uint256 localCalls = 0;
        for (uint256 i = 0; i < times; i++) {
            address sender = address(uint160(uint256(keccak256(abi.encodePacked(i, amount)))));
            vm.deal(sender, amount);
            vm.prank(sender);
            (bool ok,) = address(c).call{value: amount}("");
            if (ok) {
                localCalls++;
            }
        }
        receivedCalls += localCalls;

        // The invariant: depositsCount must equal the number of successful receive calls.
        assertEq(c.depositsCount(), receivedCalls, "depositsCount mismatch");
    }

    receive() external payable {
        // This receive is only for collecting leftover Ether, not part of the test logic
    }
}

