pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 callsToMake) public {
        // Bound to avoid OutOfGas in the loop while still allowing overflow in the buggy version.
        // 2^96 - 1 calls is enough to overflow a uint if no require is present,
        // but with the require, the transaction will revert before reaching the loop limit.
        callsToMake = uint96(bound(callsToMake, 1, type(uint96).max));

        // We need Ether to send to the contract via receive.
        // Give the test contract enough Ether to fund all calls (1 wei each).
        vm.deal(address(this), uint256(callsToMake) * 1 wei);

        // We call receive multiple times. We stop at the first revert.
        uint256 successfulCalls = 0;
        for (uint256 i = 0; i < callsToMake; i++) {
            try c.receive{value: 1 wei}() {
                successfulCalls++;
            } catch {
                break;
            }
        }

        // The general rule: after a sequence of successful receive calls,
        // depositsCount must equal the number of successful calls.
        // The reference contract maintains this because the overflow require
        // will revert before overflow, so successfulCalls == depositsCount.
        // The buggy contract lacks this require, so after many calls,
        // depositsCount can overflow and reset, breaking the equality.
        assertEq(c.depositsCount(), successfulCalls);
    }
}

