pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 n) public {
        // bound to a reasonable number of iterations to avoid timeout, but allow overflow trigger
        n = bound(n, 1, type(uint8).max+1);
        uint256 callCount = n;
        uint256[] memory amounts = new uint256[](callCount);
        // Fill with minimal amounts; receive is payable, so we need to send some wei
        for (uint256 i = 0; i < callCount; i++) {
            amounts[i] = 1;
        }
        address caller = address(0x1234);
        vm.deal(caller, callCount);
        vm.startPrank(caller);
        for (uint256 i = 0; i < callCount; i++) {
            (bool success, ) = address(c).call{value: amounts[i]}("");
            require(success, "receive call failed");
        }
        vm.stopPrank();
        // After callCount calls, depositsCount must be <= callCount.
        // Reference: equality holds because of the require preventing overflow.
        // Mutant: overflow wraps depositsCount, making it less than callCount (violating <= is fine, but we need a rule that reference passes and mutant fails).
        // Actually, mutant wraps to 0 after 2^256 calls, but with bound up to 257 we won't wrap.
        // The correct invariant: depositsCount never exceeds the number of times receive succeeded.
        // Wait, the reference always increments exactly once per call, so depositsCount == callCount.
        // Mutant also increments once per call, so depositsCount == callCount too (no overflow with small n).
        // The original bug is overflow, but with bound n <= 257, no overflow occurs, test won't distinguish.
        // We need to allow the fuzzer to choose n that could theoretically cause overflow if depositsCount is near max.
        // But depositsCount starts at 0, so we need to first set it near max, then call receive to overflow.
        // However, we can only interact through public interface; we cannot set depositsCount directly.
        // This approach fails.
    }
}

